    if(data.number(type,"UnitData","isBuildOn")!=0){float best=256;for(auto& [id,mine]:units_)if(!mine->removing && !mine->mineCover && number(mine->life)>0 && data.number(mine->type,"UnitData","canBuildOn")!=0 && (mine->owner>=12 || mine->owner==u->owner)){float distance=std::hypot(number(mine->x)-x,number(mine->y)-y);if(distance<best){best=distance;base=id;}}if(!base){reason="需要一座未被占用的金矿";return {};}point={units_.at(base)->x,units_.at(base)->y};x=number(point.x);y=number(point.y);}else{float ox=std::fmod(size[0]/2,64.f),oy=std::fmod(size[1]/2,64.f);x=std::round((x-ox)/64)*64+ox;y=std::round((y-oy)/64)*64+oy;point={real(x),real(y)};}
    if(preview)*preview=point;auto& terrain=requireWorld().data().terrain;if(x-size[0]/2<terrain.origin[0] || y-size[1]/2<terrain.origin[1] || x+size[0]/2>terrain.origin[0]+(terrain.width-1)*128 || y+size[1]/2>terrain.origin[1]+(terrain.height-1)*128){reason="建筑超出地图边界";return {};}auto cells=pathFootprint(data.field(type,"UnitData","pathTex"),point,buildingAngle()*3.14159265359f/180);unsigned prevent=placementFlags(data.field(type,"UnitBalance","preventPlace","unbuildable")),required=placementFlags(data.field(type,"UnitBalance","requirePlace"));std::span<const PathCell> ignored=base?std::span<const PathCell>(units_.at(base)->footprint):std::span<const PathCell>{};auto& pathing=requireWorld().data().pathing;if(!pathing){reason="地图缺少可用的路径网格";return {};}auto valid=[&](WorldPoint at){auto flags=(requireWorld().pathMask(at,ignored)&~32u)|(requireWorld().blighted(at)?32u:0u);return !(flags&prevent) && (flags&required)==required;};if(cells.empty() && !valid(point)){reason="无法在此地形建造";return {};}for(auto cell:cells){WorldPoint at{real(terrain.origin[0]+float(cell.index%pathing->width)*32+16),real(terrain.origin[1]+float(cell.index/pathing->width)*32+16)};if(!valid(at)){reason="地形、荒芜或阻挡不满足建造要求";return {};}}
